p,r,c=map(int,input().split())
def visit(p,r,c):
    if p==0:return 0
    h=1<<(p-1);q=2*(r>=h)+(c>=h)
    return q*h*h+visit(p-1,r%h,c%h)
print(visit(p,r,c))
